    const pintar = async () => { const bx = await p.locator('#view').boundingBox(); for (const fy of [0.105, 0.125, 0.145, 0.165, 0.18]) { await p.mouse.move(bx.x + bx.width * 0.41, bx.y + bx.height * fy); await p.mouse.down(); await p.mouse.move(bx.x + bx.width * 0.55, bx.y + bx.height * fy, { steps: 6 }); await p.mouse.up(); await sleep(120); } await sleep(400); };
    const antes = await medir();
    await T('G9', 'atalho abre a borracha e Apagar só habilita depois de pintar', async () => { await tab(p, 'looks'); await p.click('#quickErase'); await sleep(400); assert(await p.isVisible('.toolpane[data-tool=erase]'), 'ferramenta não abriu'); assert(await p.isDisabled('#erGo'), 'Apagar habilitado sem marcação'); await pintar(); assert(!(await p.isDisabled('#erGo')), 'Apagar continua desabilitado depois de pintar'); const m = await medir(); assert(m.red > antes.red * 0.5, 'marcação não apareceu'); });
    await T('G9', 'a roda do mouse aproxima dentro da borracha e Voltar desfaz', async () => { const bx = await p.locator('#view').boundingBox(); await p.mouse.move(bx.x + bx.width / 2, bx.y + bx.height / 2); await p.mouse.wheel(0, -500); await sleep(400); const z = () => p.evaluate(() => parseFloat((document.getElementById('view').style.transform.match(/scale\(([\d.]+)\)/) || [0, '1'])[1])); const e = await z(); await p.evaluate(() => window.revelaBack()); await sleep(200); assert(e > 1.1, 'não aproximou: ' + e); assert((await z()) === 1, 'Voltar não desfez o zoom'); assert(await p.isVisible('.toolpane[data-tool=erase]'), 'Voltar fechou a ferramenta junto'); return 'zoom ' + e.toFixed(2); });
