    await T('G9', 'a foto salva sai sem o objeto', async () => { const dl = p.waitForEvent('download', { timeout: 60000 }); await p.click('#saveBtn'); await dl; await p.waitForFunction(() => document.getElementById('finalImg').naturalWidth > 0); const v = await sigEl(p, '#view'), f = await sigEl(p, '#finalImg'); assert(diff(v, f) < 3, 'arquivo difere da tela em ' + diff(v, f).toFixed(1)); return 'diferença tela x arquivo ' + diff(v, f).toFixed(1); });
    await T('G9', 'desfazer traz o objeto de volta', async () => { await tool(p, 'erase'); assert(!(await p.isDisabled('#erUndo')), 'Desfazer desabilitado'); await p.click('#erUndo'); await sleep(800); await p.waitForFunction(() => document.getElementById('aiPill').hidden, null, { timeout: 180000 }); await sleep(2600); const m = await medir(); assert(m.red > antes.red * 0.8, 'objeto não voltou: ' + m.red.toFixed(0)); assert(await p.isDisabled('#erUndo'), 'Desfazer continua habilitado'); return 'vermelho do objeto de volta em ' + m.red.toFixed(0); });
    await T('G9', 'abrir outra foto limpa a marcação e o desfazer', async () => { await pintar(); await open(p, PORT); await tool(p, 'erase'); assert(await p.isDisabled('#erGo') && await p.isDisabled('#erUndo'), 'sobrou marcação ou desfazer da foto anterior'); await p.click('#toolBack'); });
